let user=null,registerMode=false,managed=[],editing=null,auditOffset=0,auditTotal=0;
const message=(text,error=false)=>{$('#message').textContent=text;$('#message').className=error?'message error':'message'};
async function busy(form,fn){const b=form.querySelector('button[type="submit"],button.primary');if(b)b.disabled=true;try{await fn()}catch(e){message(e.message,true)}finally{if(b)b.disabled=false}}
function mode(register){registerMode=register;$('#name-field').hidden=!register;$('#name-field input').required=register;$('#register-note').hidden=!register;$('#auth-title').textContent=register?'Maging bahagi ng komunidad.':'Maligayang pagbabalik.';$('#auth-submit').textContent=register?'Gumawa ng account →':'Mag-login →';$('#auth-form').elements.password.autocomplete=register?'new-password':'current-password';$('#auth-form').elements.password.minLength=register?12:1;$('#login-tab').classList.toggle('selected',!register);$('#register-tab').classList.toggle('selected',register);message('')}
$('#login-tab').onclick=()=>mode(false);$('#register-tab').onclick=()=>mode(true);
$('#auth-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const f=new FormData(e.target),b=await api(registerMode?'./api/register':'./api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(f))});user=b.user;e.target.reset();message('');await showDashboard()})};
$('#logout').onclick=async()=>{try{await api('./api/logout',{method:'POST',body:'{}'});user=null;managed=[];editing=null;$('#managed-projects').replaceChildren();$('#users-list').replaceChildren();$('#audit-list').replaceChildren();$('#youth-projects').replaceChildren();$('#project-form').reset();$('#editor').close();$('#password-form').reset();message('Naka-logout ka na.');await showDashboard()}catch(e){message(e.message,true)}};
$('#change-password').onclick=()=>{$('#password-section').hidden=!$('#password-section').hidden;$('#password-note').textContent='Gumamit ng password na hindi bababa sa 12 characters.'};
$('#password-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const f=Object.fromEntries(new FormData(e.target));if(f.password!==f.confirm)throw Error('Hindi magkatugma ang bagong password.');user=(await api('./api/password',{method:'POST',body:JSON.stringify(f)})).user;e.target.reset();message('Napalitan na ang password.');await showDashboard()})};
async function showDashboard(){const forced=user?.mustChange;$('#auth').hidden=!!user;$('#logout').hidden=!user;$('#dashboard').hidden=!user||forced;$('#password-section').hidden=!forced;if(!user)return;if(forced){$('#password-note').textContent='Palitan muna ang pansamantalang password bago gamitin ang dashboard.';return;}$('#role-label').textContent=roleText[user.role]+' DASHBOARD';$('#welcome').textContent='Kumusta, '+user.name+'.';$('#dashboard-description').textContent=user.role==='youth'?'Narito ang mga programa at serbisyong para sa iyo.':user.role==='chairman'?'Subaybayan ang mga proyekto, mga account, at lahat ng aktibidad.':'Magdagdag, mag-upload, at mag-update ng mga proyekto ng SK Vasra.';$('#youth-content').hidden=user.role!=='youth';$('#staff-content').hidden=user.role==='youth';document.querySelectorAll('.chair-only').forEach(x=>x.hidden=user.role!=='chairman');if(user.role==='youth'){const b=await api('./api/projects');$('#youth-projects').innerHTML=b.projects.map(p=>`<article class="card"><div class="cardbody"><div class="category">${esc(p.category)}</div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><p>${esc(p.status)} · ${p.progress}%</p><a href="./#projects">Tingnan sa portal ↗</a></div></article>`).join('')||'<p class="muted">Wala pang inilathalang proyekto. Balikan ang portal para sa updates.</p>'}else await selectTab('projects');}
async function selectTab(name){if(name!=='projects'&&user?.role!=='chairman')return;for(const n of ['projects','users','audit'])$('#panel-'+n).hidden=n!==name;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.tab===name));try{if(name==='projects')await loadProjects();if(name==='users')await loadUsers();if(name==='audit'){auditOffset=0;await loadAudit()}}catch(e){message(e.message,true)}}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>selectTab(b.dataset.tab));
async function loadProjects(){managed=(await api('./api/manage/projects')).projects;$('#managed-projects').innerHTML=managed.map(p=>`<article class="manage-row"><div><span class="badge-inline">${p.published?'Published':'Draft'} · ${esc(p.status)}</span><h3>${esc(p.title)}</h3><p>Gumawa: <b>${esc(p.creator_name)}</b> · ${dateText(p.created)}</p><p>Huling edit: <b>${esc(p.editor_name)}</b> · ${dateText(p.updated)}</p></div><button class="secondary" data-edit="${esc(p.id)}">I-edit ↗</button></article>`).join('')||'<div class="empty">Wala pang proyekto. Pindutin ang “Bagong proyekto” para magsimula.</div>'}
function openEditor(p=null){editing=p;const f=$('#project-form');f.reset();$('#editor-message').textContent='';$('#editor-heading').textContent=p?'I-edit ang proyekto':'Bagong proyekto';if(p){for(const n of ['title','category','description','scope','status','progress'])f.elements[n].value=p[n];f.elements.published.checked=!!p.published;}$('#current-image').innerHTML=p?.image_id?`<img class="detail-photo" src="./api/images/${encodeURIComponent(p.image_id)}" alt="Kasalukuyang larawan">`:'';$('#editor').showModal()}
$('#new-project').onclick=()=>openEditor();$('#managed-projects').onclick=e=>{const b=e.target.closest('[data-edit]');if(b)openEditor(managed.find(p=>p.id===b.dataset.edit))};$('.close').onclick=()=>$('#editor').close();
$('#project-form').elements.status.onchange=e=>{if(e.target.value==='Natapos')$('#project-form').elements.progress.value=100};
$('#project-form').onsubmit=async e=>{e.preventDefault();const f=e.target;$('#save-project').disabled=true;$('#editor-message').textContent='Sine-save…';try{const b=Object.fromEntries(new FormData(f));b.progress=Number(b.progress);b.published=f.elements.published.checked;b.version=editing?.version;b.image_id=f.elements.remove_image.checked?null:editing?.image_id||null;const file=f.elements.image.files[0];if(file){if(file.size>5242880)throw Error('Hanggang 5 MB lamang ang larawan.');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('JPG, PNG, o WebP lamang.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('Hindi mabasa ang larawan.'));r.readAsDataURL(file)});b.image_id=(await api('./api/uploads',{method:'POST',body:JSON.stringify({mime:file.type,data})})).id;}delete b.image;delete b.remove_image;await api('./api/manage/projects'+(editing?'/'+editing.id:''),{method:editing?'PUT':'POST',body:JSON.stringify(b)});$('#editor').close();message('Na-save ang proyekto at naitala sa activity log.');await loadProjects()}catch(error){$('#editor-message').textContent=error.message}finally{$('#save-project').disabled=false}};
async function loadUsers(){const b=await api('./api/users');$('#users-list').innerHTML=b.users.map(u=>`<article class="manage-row"><div><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p><span>${roleText[u.role]}</span></div>${u.role==='chairman'?'<span class="badge-inline">Chairman</span>':`<form class="role-form" data-user="${esc(u.id)}"><label>Role para kay ${esc(u.name)}<select name="role"><option value="youth" ${u.role==='youth'?'selected':''}>Kabataan</option><option value="sk" ${u.role==='sk'?'selected':''}>SK Officer</option></select></label><button class="secondary">I-save ang role</button></form>`}</article>`).join('')}
$('#users-list').onsubmit=async e=>{e.preventDefault();const form=e.target,b=form.querySelector('button');b.disabled=true;try{await api('./api/users/'+form.dataset.user+'/role',{method:'PUT',body:JSON.stringify({role:form.elements.role.value})});message('Na-update ang account access.');await loadUsers()}catch(error){message(error.message,true)}finally{b.disabled=false}};
const actions={account_registered:'Gumawa ng account',password_changed:'Nagpalit ng password',image_uploaded:'Nag-upload ng larawan',project_created:'Gumawa ng proyekto',project_updated:'Nag-edit ng proyekto',role_changed:'Nagbago ng account role'};
async function loadAudit(){const b=await api('./api/audit?offset='+auditOffset);auditTotal=b.total;$('#audit-list').innerHTML=b.events.map(e=>{const d=JSON.parse(e.details);const fields=['title','category','description','scope','status','progress','published','image_id'];const changes=d.after&&typeof d.after==='object'?fields.filter(k=>!d.before||d.before[k]!==d.after[k]).map(k=>`${k}: ${d.before?String(d.before[k]??'wala')+' → ':''}${String(d.after[k]??'wala')}`).join('\n'):e.action==='role_changed'?`${d.name}: ${d.before} → ${d.after}`:JSON.stringify(d);return `<article class="audit-row"><div><b>${esc(e.actor_name)}</b> · ${esc(actions[e.action]||e.action)}</div><small>${dateText(e.created)} · Record #${e.id}</small><details><summary>Tingnan ang detalye</summary><pre>${esc(changes)}</pre></details></article>`}).join('')||'<p>Wala pang activity.</p>';$('#audit-page').textContent=`${auditTotal?auditOffset+1:0}–${Math.min(auditOffset+50,auditTotal)} / ${auditTotal}`;$('#audit-prev').disabled=auditOffset===0;$('#audit-next').disabled=auditOffset+50>=auditTotal;}
$('#audit-prev').onclick=async()=>{auditOffset=Math.max(0,auditOffset-50);try{await loadAudit()}catch(e){message(e.message,true)}};$('#audit-next').onclick=async()=>{auditOffset+=50;try{await loadAudit()}catch(e){message(e.message,true)}};
api('./api/me').then(async b=>{user=b.user;await showDashboard()}).catch(e=>{$('#auth').hidden=false;message(e.message,true)});
